module prob_calc(\n    input [7:0] f,\n    input [7:0] w,\n    input [7:0] h,\n    output reg [31:0] p\n);\n\n    localparam [31:0] MOD = 32'd1000000007;\n    localparam [4:0] MAX_N = 5'd16;\n\n    // Binomial coefficient table: C[n][k]\n    reg [15:0] C [0:MAX_N][0:MAX_N];\n\n    // Initialize C using Pascal\'s triangle\n    integer i, j;\n    initial begin\n        // Initialize all to 0\n        for (i = 0; i <= MAX_N; i = i + 1) begin\n            for (j = 0; j <= MAX_N; j = j + 1) begin\n                C[i][j] = 16'd0;\n            end\n        end\n        // Compute Pascal\'s triangle\n        for (i = 0; i <= MAX_N; i = i + 1) begin\n            C[i][0] = 16'd1;\n            if (i >= 1) C[i][i] = 16'd1;\n            for (j = 1; j < i; j = j + 1) begin\n                if (i >= 1) C[i][j] = C[i-1][j-1] + C[i-1][j];\n            end\n        end\n    end\n\n    // Function to lookup modular inverse (precomputed for possible totals)\n    function [31:0] inv_lookup;\n        input [15:0] total;\n        begin\n            case(total)\n                16'd1: inv_lookup = 32'd1;\n                16'd2: inv_lookup = 32'd500000004;\n                16'd3: inv_lookup = 32'd333333336;\n                16'd6: inv_lookup = 32'd166666668;\n                16'd20: inv_lookup = 32'd850000006;\n                default: inv_lookup = 32'd0;\n            endcase\n        end\n    endfunction\n\n    // Combinational logic\n    reg [15:0] total;\n    reg [15:0] liked;\n    reg [15:0] kmax;\n    reg [15:0] term1;\n    reg [15:0] term2;\n    reg [15:0] n2;\n    reg [15:0] r2;\n    integer k;\n    reg [31:0] inv_total;\n\n    always @(*) begin\n        // Compute total = C[f + w][w]\n        total = C[f + w][w];\n\n        // Compute liked\n        if (w == 8'd0) begin\n            liked = 16'd1;\n        end else begin\n            liked = 16'd0;\n            // Compute kmax = min(w / (h+1), f+1)\n            if (h == 8'hFF) begin\n                kmax = 16'd0;\n            end else begin\n                kmax = w / (h + 8'd1);\n            end\n            if (kmax > f + 16'd1) kmax = f + 16'd1;\n\n            for (k = 1; k <= kmax; k = k + 1) begin\n                term1 = C[f + 16'd1][k];\n                n2 = w - (k * (h + 8'd1)) - 16'd1;\n                r2 = k - 16'd1;\n                if (n2 >= r2 && r2 >= 16'd0 && n2 < 16'd65535) begin\n                    term2 = C[n2][r2];\n                end else begin\n                    term2 = 16'd0;\n                end\n                if (term2 != 16'd0) begin\n                    liked = liked + term1 * term2;\n                end\n            end\n        end\n\n        // Lookup inverse\n        inv_total = inv_lookup(total);\n\n        // Compute result\n        p = (liked * inv_total) % MOD;\n    end\n\nendmodule